(() => {
  'use strict';

  const config =
    window.KIYT_CONSOLE_CONFIG || {};

  const email =
    document.querySelector('#email');

  const emailForm =
    document.querySelector('#email-form');

  const emailError =
    document.querySelector('#email-error');

  const emailSubmit =
    document.querySelector('#email-submit');

  const panel =
    document.querySelector('.access-panel');

  const viewport =
    document.querySelector('#auth-viewport');

  const emailStep =
    document.querySelector('#auth-email-step');

  const credentialStep =
    document.querySelector('#auth-register-step');

  const credentialForm =
    document.querySelector('#register-form');

  const credentialEmail =
    document.querySelector('#register-email');

  const firstName =
    document.querySelector('#first-name');

  const lastName =
    document.querySelector('#last-name');

  const password =
    document.querySelector('#register-password');

  const repeatPassword =
    document.querySelector('#repeat-password');

  const error =
    document.querySelector('#register-error');

  const feedback =
    document.querySelector('#register-feedback');

  const heading =
    credentialStep.querySelector(
      '.register-heading h2'
    );

  const subheading =
    credentialStep.querySelector(
      '.register-heading p'
    );

  const submit =
    document.querySelector('#register-submit');

  const submitText =
    submit.querySelector('span');

  const firstField =
    firstName.closest('.register-field');

  const lastField =
    lastName.closest('.register-field');

  const repeatField =
    repeatPassword.closest('.register-field');

  const dialog =
    document.querySelector('#info-dialog');

  let dialogTrigger = null;

  function fit(step) {
    if (
      !viewport ||
      !step
    ) {
      return;
    }

    viewport.style.height =
      `${Math.ceil(step.scrollHeight)}px`;
  }

  function setBusy(
    button,
    value
  ) {
    if (button) {
      button.disabled = value;
    }
  }

  function safeUrl(
    value,
    allowMail = false
  ) {
    if (
      typeof value !== 'string' ||
      !value.trim()
    ) {
      return null;
    }

    try {
      const url =
        new URL(
          value,
          location.href
        );

      const local =
        url.origin === location.origin &&
        url.protocol === 'http:';

      if (
        url.protocol === 'https:' ||
        local ||
        (
          allowMail &&
          url.protocol === 'mailto:'
        )
      ) {
        return url.href;
      }
    } catch {}

    return null;
  }

  function openInfo(
    trigger,
    title,
    message,
    eyebrow = 'KIYT CONSOLE'
  ) {
    if (!dialog) {
      return;
    }

    dialogTrigger = trigger;

    document.querySelector(
      '#dialog-title'
    ).textContent = title;

    document.querySelector(
      '#dialog-description'
    ).textContent = message;

    document.querySelector(
      '#dialog-eyebrow'
    ).textContent = eyebrow;

    dialog.showModal();

    dialog
      .querySelector('.dialog-done')
      ?.focus();
  }

  if (dialog) {
    dialog.addEventListener(
      'close',
      () => {
        dialogTrigger?.focus();
      }
    );

    dialog.addEventListener(
      'click',
      event => {
        if (
          event.target !== dialog
        ) {
          return;
        }

        const rect =
          dialog.getBoundingClientRect();

        if (
          event.clientX < rect.left ||
          event.clientX > rect.right ||
          event.clientY < rect.top ||
          event.clientY > rect.bottom
        ) {
          dialog.close();
        }
      }
    );
  }

  const documentation =
    document.querySelector(
      '#documentation-link'
    );

  const docsUrl =
    safeUrl(
      config.documentationUrl
    );

  if (documentation) {
    if (docsUrl) {
      documentation.href =
        docsUrl;
    } else {
      documentation.addEventListener(
        'click',
        event => {
          event.preventDefault();

          openInfo(
            documentation,
            'Documentation is on its way.',
            'The KIYT documentation link will be added here. In the meantime, our team can help you get started.',
            'DEVELOPER RESOURCES'
          );
        }
      );
    }
  }

  const salesUrl =
    safeUrl(
      config.salesUrl,
      true
    );

  if (salesUrl) {
    document
      .querySelectorAll(
        '[data-sales-link], .dialog-contact'
      )
      .forEach(link => {
        link.href =
          salesUrl;
      });
  }

  const year =
    document.querySelector(
      '#copyright-year'
    );

  if (year) {
    year.textContent =
      new Date().getFullYear();
  }

  function clearEmailError() {
    emailError.hidden = true;
    emailError.textContent = '';

    email.removeAttribute(
      'aria-invalid'
    );
  }

  function showEmailError(message) {
    emailError.textContent =
      message;

    emailError.hidden = false;

    email.setAttribute(
      'aria-invalid',
      'true'
    );

    email.focus();

    fit(emailStep);
  }

  function clearCredentialError() {
    error.hidden = true;
    error.textContent = '';

    if (feedback) {
      feedback.hidden = true;
    }

    [
      firstName,
      lastName,
      password,
      repeatPassword
    ].forEach(input => {
      input.removeAttribute(
        'aria-invalid'
      );
    });
  }

  function showCredentialError(
    input,
    message
  ) {
    error.textContent =
      message;

    error.hidden =
      false;

    input?.setAttribute(
      'aria-invalid',
      'true'
    );

    input?.focus();

    fit(credentialStep);
  }

  async function readJson(
    response
  ) {
    try {
      return await response.json();
    } catch {
      return {};
    }
  }

  function apiMessage(
    body,
    fallback
  ) {
    if (
      typeof body?.message === 'string'
    ) {
      return body.message;
    }

    if (
      typeof body?.error === 'string'
    ) {
      return body.error;
    }

    if (
      typeof body?.error?.message ===
      'string'
    ) {
      return body.error.message;
    }

    return fallback;
  }

  function configure(mode) {
    const isLogin =
      mode === 'login';

    credentialForm.dataset.mode =
      mode;

    credentialEmail.value =
      email.value;

    firstField.hidden =
      isLogin;

    lastField.hidden =
      isLogin;

    repeatField.hidden =
      isLogin;

    firstName.required =
      !isLogin;

    lastName.required =
      !isLogin;

    repeatPassword.required =
      !isLogin;

    password.setAttribute(
      'autocomplete',
      isLogin
        ? 'current-password'
        : 'new-password'
    );

    heading.textContent =
      isLogin
        ? 'Intelligence awaits.'
        : 'Welcome to Cognitive Playground';

    subheading.textContent =
      isLogin
        ? 'Sign in to your cognitive workspace.'
        : 'Fill This Form';

    submitText.textContent =
      isLogin
        ? 'Log in'
        : 'Register';

    clearCredentialError();

    panel.dataset.authStep =
      'register';

    emailStep.setAttribute(
      'aria-hidden',
      'true'
    );

    credentialStep.setAttribute(
      'aria-hidden',
      'false'
    );

    fit(credentialStep);

    setTimeout(
      () => {
        (
          isLogin
            ? password
            : firstName
        ).focus();
      },
      matchMedia(
        '(prefers-reduced-motion: reduce)'
      ).matches
        ? 0
        : 430
    );
  }

  email.addEventListener(
    'input',
    () => {
      clearEmailError();
      fit(emailStep);
    }
  );

  emailForm.addEventListener(
    'submit',
    async event => {
      event.preventDefault();

      email.value =
        email.value
          .trim()
          .toLowerCase();

      clearEmailError();

      if (!email.value) {
        showEmailError(
          'Enter your email address to continue.'
        );
        return;
      }

      if (!email.validity.valid) {
        showEmailError(
          'Enter a valid email address, like you@company.com.'
        );
        return;
      }

      setBusy(
        emailSubmit,
        true
      );

      try {
        const response =
          await fetch(
            '/api/auth-flow/account-status',
            {
              method: 'POST',
              credentials:
                'same-origin',
              headers: {
                'Content-Type':
                  'application/json'
              },
              body:
                JSON.stringify({
                  email:
                    email.value
                })
            }
          );

        const body =
          await readJson(
            response
          );

        if (!response.ok) {
          showEmailError(
            apiMessage(
              body,
              'Unable to continue right now.'
            )
          );

          return;
        }

        configure(
          body.exists
            ? 'login'
            : 'register'
        );
      } catch {
        showEmailError(
          'Unable to continue right now.'
        );
      } finally {
        setBusy(
          emailSubmit,
          false
        );
      }
    }
  );

  credentialForm.addEventListener(
    'input',
    () => {
      clearCredentialError();
      fit(credentialStep);
    }
  );

  credentialForm.addEventListener(
    'submit',
    async event => {
      event.preventDefault();

      clearCredentialError();

      const mode =
        credentialForm.dataset.mode ??
        'register';

      const userEmail =
        credentialEmail.value
          .trim()
          .toLowerCase();

      if (!password.value) {
        showCredentialError(
          password,
          'Enter your password.'
        );

        return;
      }

      if (
        password.value.length < 8
      ) {
        showCredentialError(
          password,
          'Password must be at least 8 characters.'
        );

        return;
      }

      if (
        password.value.length > 128
      ) {
        showCredentialError(
          password,
          'Password must be 128 characters or fewer.'
        );

        return;
      }

      if (mode === 'login') {
        setBusy(
          submit,
          true
        );

        try {
          const response =
            await fetch(
              '/api/auth/sign-in/email',
              {
                method: 'POST',
                credentials:
                  'same-origin',
                headers: {
                  'Content-Type':
                    'application/json'
                },
                body:
                  JSON.stringify({
                    email:
                      userEmail,
                    password:
                      password.value,
                    rememberMe:
                      true
                  })
              }
            );

          const body =
            await readJson(
              response
            );

          if (!response.ok) {
            showCredentialError(
              password,
              apiMessage(
                body,
                'Email or password is incorrect.'
              )
            );

            return;
          }

          window.location.assign(
            '/myaccount'
          );
        } catch {
          showCredentialError(
            password,
            'Unable to log in right now.'
          );
        } finally {
          setBusy(
            submit,
            false
          );
        }

        return;
      }

      firstName.value =
        firstName.value.trim();

      lastName.value =
        lastName.value.trim();

      if (!firstName.value) {
        showCredentialError(
          firstName,
          'Enter your first name.'
        );

        return;
      }

      if (!lastName.value) {
        showCredentialError(
          lastName,
          'Enter your last name.'
        );

        return;
      }

      if (!repeatPassword.value) {
        showCredentialError(
          repeatPassword,
          'Repeat your password.'
        );

        return;
      }

      if (
        password.value !==
        repeatPassword.value
      ) {
        showCredentialError(
          repeatPassword,
          'Passwords do not match.'
        );

        return;
      }

      setBusy(
        submit,
        true
      );

      try {
        const response =
          await fetch(
            '/api/auth/sign-up/email',
            {
              method: 'POST',
              credentials:
                'same-origin',
              headers: {
                'Content-Type':
                  'application/json'
              },
              body:
                JSON.stringify({
                  email:
                    userEmail,
                  password:
                    password.value,
                  name:
                    `${firstName.value} ${lastName.value}`,
                  firstName:
                    firstName.value,
                  lastName:
                    lastName.value
                })
            }
          );

        const body =
          await readJson(
            response
          );

        if (!response.ok) {
          showCredentialError(
            password,
            apiMessage(
              body,
              'Unable to register this account.'
            )
          );

          return;
        }

        window.location.assign(
          '/myaccount'
        );
      } catch {
        showCredentialError(
          password,
          'Unable to register right now.'
        );
      } finally {
        setBusy(
          submit,
          false
        );
      }
    }
  );

  requestAnimationFrame(
    () => fit(emailStep)
  );

  window.addEventListener(
    'resize',
    () => {
      fit(
        panel.dataset.authStep ===
          'register'
          ? credentialStep
          : emailStep
      );
    }
  );
})();
